using AfriWallet.Compliance.Readiness.Models;
namespace AfriWallet.Compliance.Readiness.Checks;
public sealed class DeliveryPresenceCheck:IComplianceReadinessCheck { public string Code=>"CMP-RDY-001"; public Task<ReadinessCheck> ExecuteAsync(string root,CancellationToken ct=default){ct.ThrowIfCancellationRequested();Dictionary<string,string[]> required=new(){["0016.1"]=["backend","src","CompliancePlatform","ComplianceProfile.Domain"],["0016.2"]=["backend","src","Compliance","IdentityVerification.Domain"],["0016.3"]=["backend","src","Compliance","Screening.Domain"],["0016.4"]=["backend","src","Compliance","TransactionMonitoring.Domain"],["0016.5"]=["backend","src","Compliance","RiskScoring.Domain"],["0016.6"]=["backend","src","Compliance","CaseManagement.Domain"]};var missing=required.Where(x=>!RepositoryCheckUtilities.DirectoryExists(root,x.Value)).Select(x=>x.Key).ToArray();return Task.FromResult(new ReadinessCheck(Code,"Required compliance deliveries present",missing.Length==0?ReadinessStatus.Passed:ReadinessStatus.Failed,missing.Length==0?"0016.1 through 0016.6 present":$"Missing: {string.Join(", ",missing)}"));} }